from itertools import product
from typing import Callable, Tuple

Point = Tuple[int, ...]


def expect(f: Callable[[Point], float], n: int) -> float:
    pts = list(product((0, 1), repeat=n))
    return sum(f(x) for x in pts) / len(pts)


def cov(f: Callable[[Point], float], g: Callable[[Point], float], n: int) -> float:
    return expect(lambda x: f(x) * g(x), n) - expect(f, n) * expect(g, n)


def verify_variance_identity() -> None:
    """Confirm Cov(f,f) = E[f](1-E[f]) for a family of monotone Boolean functions."""
    tests = [
        ("dictatorship x_0, n=1", lambda x: float(x[0]), 1),
        ("AND, n=2", lambda x: float(x[0] and x[1]), 2),
        ("OR, n=2", lambda x: float(x[0] or x[1]), 2),
        ("majority-3, n=3", lambda x: float(sum(x) >= 2), 3),
        ("threshold>=2, n=4", lambda x: float(sum(x) >= 2), 4),
    ]
    for name, f, n in tests:
        m = expect(f, n)
        print(f"{name:24s}  Cov(f,f)={cov(f, f, n):.6f}  "
              f"E[f](1-E[f])={m*(1-m):.6f}")


if __name__ == "__main__":
    verify_variance_identity()

