from itertools import product
from typing import Callable, List, Tuple

Point = Tuple[int, ...]
BoolFn = Callable[[Point], float]


def cube(n: int) -> List[Point]:
    """Enumerate the 2^n vertices of the Boolean cube {0,1}^n."""
    return list(product((0, 1), repeat=n))


def expect(f: BoolFn, n: int) -> float:
    """Uniform-measure average E[f] = (1/2^n) * sum_x f(x)."""
    pts = cube(n)
    return sum(f(x) for x in pts) / len(pts)


def covariance(f: BoolFn, g: BoolFn, n: int) -> float:
    """Covariance Cov(f,g) = E[f*g] - E[f]*E[g] under the uniform measure."""
    e_fg = expect(lambda x: f(x) * g(x), n)
    return e_fg - expect(f, n) * expect(g, n)

