function FKG_CERTIFICATE(f, g, n):
    inc <- IS_INCREASING(f, n) and IS_INCREASING(g, n)
    cov <- COVARIANCE(f, g, n)
    return (inc, cov)   # if inc then cov >= 0 (Harris-FKG)

function IS_INCREASING(f, n):
    for each x in {0,1}^n:
        for each y in {0,1}^n with x <= y:
            if f(x) > f(y): return False
    return True
